    std::string json(reinterpret_cast<char*>(out.data()),encoded.value());CHECK(json.find("\"sequence\":\"18446744073709551615\"")!=std::string::npos);CHECK(json.find("\"value\":false")!=std::string::npos);CHECK(json.find("\"sampled_at_ns\":\"0\"")!=std::string::npos);CHECK(json.find("\"readers\":[]")!=std::string::npos);CHECK(json.find("\"numeric_code\":4294967295")!=std::string::npos);CHECK(json.find("q\\\"\\\\\\n")!=std::string::npos);CHECK(json.find("18446744073709551615")!=std::string::npos);
