void test_maximum_snapshot_counted_size()
{
    w::ListResponse list;auto s=maximum_snapshot(list);w::StatusContext context{&list};const auto size=w::status_json_size(s,context);CHECK(size);if(!size){std::fprintf(stderr,"full snapshot validation error: %u scope=%u list=%u\n",static_cast<unsigned>(size.error()),static_cast<unsigned>(w::validate_status_response_scope(s)),static_cast<unsigned>(w::validate_list_response(list)));for(std::size_t i=0U;i<s.receivers.value.count;++i){auto probe=s;probe.scope.kind=w::ScopeKind::receiver;probe.scope.id=i;probe.functions.present=false;probe.readers.present=false;probe.receivers.value.items[0]=probe.receivers.value.items[i];probe.receivers.value.count=1U;w::StatusContext one{&list};const auto result=w::status_json_size(probe,one);if(!result)std::fprintf(stderr,"receiver %zu error %u\n",i,static_cast<unsigned>(result.error()));}return;}CHECK(size.value()>65536U);std::vector<std::uint8_t> output(size.value(),0xa5U);const auto short_result=w::encode_status_json(s,context,{output.data(),size.value()-1U});CHECK(!short_result&&short_result.error()==Error::BUFFER_TOO_SMALL);for(auto b:output)CHECK(b==0xa5U);const auto encoded=w::encode_status_json(s,context,{output.data(),output.size()});CHECK(encoded&&encoded.value()==size.value());CHECK(output.back()=='\n');
}
